style.css:
@-moz-document domain("youtube.com") {
:root {
  --red: #D90026;
  --blue: #0033A0;
  --orange: #F2A800;
  --dark: #100b18;
  --card: #1c1424;
}


html, body, ytd-app {
  background-color: var(--dark) !important;
  background-image:
    radial-gradient(ellipse at 15% 30%, #50101d55, transparent 55%),
    radial-gradient(ellipse at 85% 70%, #002d8050, transparent 55%),
    linear-gradient(145deg, #160810, #080d20 55%, #24100b) !important;
}


#contentContainer,
#page-manager,
ytd-browse,
ytd-search {
  background: transparent !important;
}


#masthead-container,
#masthead {
  background: linear-gradient(
    90deg,
    #a90020,
    #0033a0 50%,
    #d98200
  ) !important;
}


ytd-topbar-logo-renderer {
  filter: drop-shadow(0 0 5px #ff9b43);
}


ytd-guide-renderer,
#guide-content,
ytd-mini-guide-renderer {
  background: linear-gradient(
    180deg,
    #210b19,
    #10152d 60%,
    #32160b
  ) !important;
}


ytd-guide-entry-renderer yt-icon,
ytd-mini-guide-entry-renderer yt-icon {
  filter: drop-shadow(0 0 4px #ff6a36);
}


ytd-guide-entry-renderer:nth-child(1) yt-icon {
  color: var(--red) !important;
}

ytd-guide-entry-renderer:nth-child(2) yt-icon {
  color: #ff526b !important;
}

ytd-guide-entry-renderer:nth-child(3) yt-icon {
  color: var(--orange) !important;
}


ytd-guide-entry-renderer[active] {
  background: linear-gradient(
    90deg,
    #d90026,
    #0033a0,
    #f2a800
  ) !important;
  border-radius: 12px !important;
}


ytd-rich-item-renderer,
ytd-video-renderer,
ytd-compact-video-renderer {
  background: var(--card) !important;
  border: 1px solid #ffffff12 !important;
  border-radius: 14px !important;
  overflow: hidden;
}


ytd-rich-item-renderer:hover,
ytd-video-renderer:hover {
  border-color: var(--orange) !important;
  box-shadow: 0 0 12px #d9002640;
}


#search-input {
  border-color: var(--blue) !important;
}

#search-icon-legacy,
ytd-searchbox button {
  background: linear-gradient(
    90deg,
    var(--red),
    var(--blue),
    var(--orange)
  ) !important;
  color: white !important;
}


yt-chip-cloud-chip-renderer {
  background: #241727 !important;
  border: 1px solid #0033a0 !important;
  border-radius: 20px !important;
}

yt-chip-cloud-chip-renderer[selected] {
  background: linear-gradient(
    90deg,
    var(--red),
    var(--blue),
    var(--orange)
  ) !important;
}


yt-icon,
yt-icon-button,
#button {
  transition: 0.2s ease !important;
}

yt-icon:hover {
  filter: drop-shadow(0 0 5px var(--orange));
}


ytd-reel-shelf-renderer {
  border-top: 2px solid var(--red);
}


yt-button-shape button,
ytd-button-renderer button {
  border-radius: 12px !important;
}


ytd-notification-topbar-button-renderer,
ytd-topbar-menu-button-renderer {
  color: var(--orange) !important;
}


.ytp-play-progress {
  background: linear-gradient(
    90deg,
    var(--red),
    var(--blue),
    var(--orange)
  ) !important;
}


.ytp-volume-slider-handle {
  background: var(--orange) !important;
}


::-webkit-scrollbar {
  width: 9px;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(
    var(--red),
    var(--blue),
    var(--orange)
  );
  border-radius: 10px;
}


a:hover {
  color: var(--orange) !important;
}


ytd-guide-section-renderer {
  border-color: #d9002640 !important;
}
  

@-moz-document domain("youtube.com") {
  body::after {
    content: "";
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 210px;
    pointer-events: none;
    z-index: 9999;
    opacity: 0.42;
    background-image: url("data:image/png;base64,");
    background-repeat: no-repeat;
    background-position: center bottom 15px;
    background-size: min(850px, 95vw) auto;
  }
  
}
}
